import * as http from 'http';
import { createServer } from './server';

let server: http.Server;
let port: number;

beforeAll((done) => {
  server = createServer();
  server.listen(0, () => {
    port = (server.address() as any).port;
    done();
  });
});

afterAll((done) => server.close(done));

async function req(method: string, path: string, body?: object) {
  return new Promise<{ status: number; body: any }>((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const options = {
      hostname: '127.0.0.1',
      port,
      path,
      method,
      headers: data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {},
    };
    const r = http.request(options, (res) => {
      let responseBody = '';
      res.on('data', chunk => responseBody += chunk);
      res.on('end', () => resolve({ status: res.statusCode!, body: JSON.parse(responseBody) }));
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

test('GET /todos returns empty array', async () => {
  const r = await req('GET', '/todos');
  expect(r.status).toBe(200);
  expect(Array.isArray(r.body)).toBe(true);
});

test('POST /todos creates a todo', async () => {
  const r = await req('POST', '/todos', { title: 'Buy milk' });
  expect(r.status).toBe(201);
  expect(r.body.title).toBe('Buy milk');
  expect(r.body.id).toBeGreaterThan(0);
});

test('DELETE /todos/:id removes the todo', async () => {
  const created = await req('POST', '/todos', { title: 'Delete me' });
  const id = created.body.id;
  const del = await req('DELETE', `/todos/${id}`);
  expect(del.status).toBe(204);
  const list = await req('GET', '/todos');
  expect(list.body.find((t: any) => t.id === id)).toBeUndefined();
});

test('DELETE /todos/:id returns 404 for unknown id', async () => {
  const r = await req('DELETE', '/todos/999999');
  expect(r.status).toBe(404);
});
